"plx-pingin\"><circle r=\"15\" fill=\"#FFB400\" stroke=\"#151515\" stroke-width=\"3\"/><g fill=\"#151515\"><ellipse cx=\"0\" cy=\"3.5\" rx=\"5\" ry=\"4\"/><circle cx=\"-6\" cy=\"-2\" r=\"2.1\"/><circle cx=\"-2.2\" cy=\"-6\" r=\"2.2\"/><circle cx=\"2.2\" cy=\"-6\" r=\"2.2\"/><circle cx=\"6\" cy=\"-2\" r=\"2.1\"/></g></g></g></g><g class=\"plx-drop\"><image class=\"plx-logo\" href=\"data:image/png;base64,\" x=\"88.9\" y=\"122.0\" width=\"142.2\" height=\"154.0\"/><ellipse class=\"plx-lid\" cx=\"134.0\" cy=\"199.8\" rx=\"7.8\" ry=\"8.4\"/><ellipse class=\"plx-lid\" cx=\"170.1\" cy=\"203.4\" rx=\"7.8\" ry=\"7.3\"/></g></svg>';\n  var WORD='Pawprint', TAG='Gotta spot \\u2019em all.';\n  function seen(){try{return sessionStorage.getItem('pawlaunch')==='1'}catch(e){return false}}\n  function mark(){try{sessionStorage.setItem('pawlaunch','1')}catch(e){}}\n  function show(o){\n    o=o||{};\n    if((o.once||'session')==='session'&&seen()){return Promise.resolve()}\n    var reduced=root.matchMedia&&root.matchMedia('(prefers-reduced-motion: reduce)').matches;\n    var calm=!!o.calm||reduced;\n    var minMs=o.minMs!=null?o.minMs:(calm?900:2600);\n    var maxMs=o.maxMs||6000;\n    var el=document.createElement('div');\n    el.className='plx'+(calm?' plx-calm':'')+(o.dark?' plx-dark':'');\n    el.setAttribute('role','status');el.setAttribute('aria-label','Pawprint is loading');\n    var letters='';for(var i=0;i<WORD.length;i++){letters+='<span style=\"--k:'+i+'\">'+WORD[i]+'</span>'}\n    el.innerHTML='<div class=\"plx-map\"></div><div class=\"plx-stage\"><div class=\"plx-art\">'+SVG+'</div><div class=\"plx-word\" aria-hidden=\"true\">'+letters+'</div><div class=\"plx-tag\">'+TAG+'</div></div><button class=\"plx-skip\" type=\"button\">Skip</button>';\n    document.body.appendChild(el);\n    var prev=document.body.style.overflow;document.body.style.overflow='hidden';\n    var done=false,t0=Date.now();\n    return new Promise(function(resolve){\n      var dots=document.createElement('div');dots.className='plx-dots';dots.innerHTML='<i></i><i></i><i></i>';\n      function finish(){\n        if(done)return;done=true;mark();\n        el.classList.add('plx-out');\n        setTimeout(function(){el.remove();document.body.style.overflow=prev;o.onDone&&o.onDone();resolve()},calm?300:450);\n      }\n      var skip=el.querySelector('.plx-skip');\n      skip.addEventListener('click',finish);\n      el.addEventListener('click',function(){if(Date.now()-t0>1200)finish()});\n      var rd=typeof o.ready==='function'?o.ready():o.ready;\n      var minP=new Promise(function(r){setTimeout(r,minMs)});\n      var maxP=new Promise(function(r){setTimeout(r,maxMs)});\n      var rdy=Promise.resolve(rd).catch(function(){});\n      if(!calm&&navigator.vibrate&&o.haptic!==false)setTimeout(function(){if(!done)try{navigator.vibrate(12)}catch(e){}},1350);\n      setTimeout(function(){if(!done){el.querySelector('.plx-stage').appendChild(dots)}},minMs+150);\n      Promise.race([Promise.all([minP,rdy]),maxP]).then(finish);\n    });\n  }\n  root.PawLaunch={show:show,reset:function(){try{sessionStorage.removeItem('pawlaunch')}catch(e){}}};\n})(window);\n";
const PAWLAUNCH_CSS = "/* PawLaunch – launch screen for Pawprint. transform/opacity only. */\n.plx{position:fixed;inset:0;z-index:99999;display:flex;align-items:center;justify-content:center;\n  background:#FAF8F4;color:#151515;--plx-amber:#FFB400;--plx-stone:#8C8A84;\n  padding:env(safe-area-inset-top) env(safe-area-inset-right) env(safe-area-inset-bottom) env(safe-area-inset-left);\n  font-family:'Fredoka',system-ui,sans-serif;opacity:1;transition:opacity .45s ease,transform .45s ease}\n:is([data-theme=\"dark\"],.pl-dark) .plx,.plx.plx-dark{background:#151515;color:#FAF8F4;--plx-stone:#A9A7A0}\n.plx.plx-out{opacity:0;transform:scale(1.04);pointer-events:none}\n.plx-stage{position:relative;width:min(86vw,340px);display:flex;flex-direction:column;align-items:center}\n.plx-art{position:relative;width:100%;aspect-ratio:320/360}\n.plx-art svg{position:absolute;inset:0;width:100%;height:100%;overflow:visible}\n\n/* paws walk up toward the spot */\n.plx-paw{opacity:0;transform-box:fill-box;transform-origin:center;animation:plx-step .45s cubic-bezier(.3,.7,.3,1) forwards,plx-gone .3s ease-in 1.15s forwards;animation-delay:calc(var(--i)*.2s + .05s),1.2s}\n.plx-paw .pp{fill:currentColor;animation:plx-ink .6s linear forwards;animation-delay:calc(var(--i)*.2s + .05s)}\n@keyframes plx-step{0%{opacity:0;transform:scale(.3) translateY(8px)}55%{opacity:1;transform:scale(1.15)}100%{opacity:.9;transform:scale(1)}}\n@keyframes plx-ink{0%,30%{fill:var(--plx-amber)}100%{fill:currentColor}}\n@keyframes plx-gone{to{opacity:0;transform:scale(.8)}}\n\n/* logo drops like a map pin */\n.plx-shadow{transform-origin:160px 276px;transform-box:view-box;opacity:0;animation:plx-shadow .5s ease-out 1s forwards}\n.plx-drop{transform-box:view-box;transform-origin:160px 276px;opacity:0;animation:plx-drop .7s cubic-bezier(.3,0,.4,1) 1s forwards}\n.plx-logo{fill:currentColor}\n.plx-ripple{transform-box:view-box;transform-origin:160px 276px;opacity:0;animation:plx-ripple .9s ease-out 1.5s forwards}\n.plx-ripple.b{animation-delay:1.68s}\n@keyframes plx-drop{\n  0%{opacity:0;transform:translateY(-120px) scale(.92,1.08)}\n  8%{opacity:1}\n  55%{transform:translateY(0) scale(1.14,.82)}\n  72%{transform:translateY(-16px) scale(.96,1.05)}\n  88%{transform:translateY(0) scale(1.04,.96)}\n  100%{opacity:1;transform:none}}\n@keyframes plx-shadow{0%{opacity:0;transform:scale(.3)}60%{opacity:.18;transform:scale(1)}100%{opacity:.14;transform:scale(1)}}\n@keyframes plx-ripple{0%{opacity:.7;transform:scale(.2)}100%{opacity:0;transform:scale(2.6)}}\n\n/* wordmark + tagline */\n.plx-word{display:flex;font-weight:700;font-size:clamp(34px,10vw,46px);letter-spacing:.01em;line-height:1;margin-top:2px}\n.plx-word span{display:inline-block;opacity:0;transform:translateY(14px);animation:plx-rise .45s cubic-bezier(.2,.9,.3,1.3) forwards;animation-delay:calc(1.6s + var(--k)*.045s)}\n.plx-word .dot{color:var(--plx-amber)}\n.plx-tag{margin-top:10px;font-weight:500;font-size:clamp(14px,4vw,17px);color:var(--plx-stone);opacity:0;animation:plx-fade .5s ease 2.05s forwards}\n@keyframes plx-rise{to{opacity:1;transform:none}}\n@keyframes plx-fade{to{opacity:1}}\n.plx-skip{position:absolute;right:16px;bottom:calc(16px + env(safe-area-inset-bottom));font:500 13px 'Fredoka',system-ui,sans-serif;color:var(--plx-stone);background:none;border:0;opacity:0;animation:plx-fade .4s ease 1s forwards;cursor:pointer;padding:8px}\n\n/* calm: no movement, just a soft fade-in of the finished logo */\n.plx-calm .plx-paw,.plx-calm .plx-shadow,.plx-calm .plx-ripple{display:none}\n.plx-calm .plx-drop,.plx-calm .plx-word span,.plx-calm .plx-tag{animation:plx-fade .5s ease forwards!important;animation-delay:0s!important;transform:none!important}\n.plx-calm .plx-tag{animation-delay:.15s!important}\n@media (prefers-reduced-motion:reduce){\n  .plx .plx-paw,.plx .plx-shadow,.plx .plx-ripple{display:none}\n  .plx .plx-drop,.plx .plx-word span,.plx .plx-tag{animation:plx-fade .5s ease forwards!important;animation-delay:0s!important;transform:none!important}\n  .plx{transition:opacity .3s ease;} .plx.plx-out{transform:none}\n}\n:is([data-theme=\"dark\"],.pl-dark) .plx .plx-logo,.plx.plx-dark .plx-logo{filter:invert(1) brightness(.98)}\n\n/* v2 extras */\n.plx-disc{transform-box:view-box;transform-origin:160px 200px;opacity:0;transform:scale(.2);animation:plx-disc .55s cubic-bezier(.2,.9,.3,1.2) 1.22s forwards}\n@keyframes plx-disc{0%{opacity:0;transform:scale(.2)}40%{opacity:.22}100%{opacity:.16;transform:scale(1)}}\n.plx-lid{fill:currentColor;transform-box:fill-box;transform-origin:center;transform:scaleY(0);animation:plx-blink 2.4s ease-in-out -.1s infinite}\n@keyframes plx-blink{0%,92%,100%{transform:scaleY(0)}95.5%{transform:scaleY(1.05)}}\n.plx-drop{animation-name:plx-drop}\n.plx-dots{display:flex;gap:7px;margin-top:18px;position:absolute;bottom:-26px}\n.plx-dots i{width:8px;height:8px;border-radius:50%;background:var(--plx-amber);animation:plx-dot 1s ease-in-out infinite}\n.plx-dots i:nth-child(2){animation-delay:.15s}.plx-dots i:nth-child(3){animation-delay:.3s}\n@keyframes plx-dot{0%,100%{transform:translateY(0);opacity:.4}50%{transform:translateY(-6px);opacity:1}}\n.plx-out .plx-art{transform:scale(.9);transition:transform .45s ease}\n.plx-calm .plx-disc,.plx-calm .plx-lid{display:none}\n@media (prefers-reduced-motion:reduce){.plx .plx-disc,.plx .plx-lid,.plx .plx-dots i{animation:none}.plx .plx-disc,.plx .plx-lid{display:none}}\n\n/* v3: map backdrop + nearby-cat pings */\n.plx-map{position:absolute;inset:0;pointer-events:none;opacity:0;animation:plx-fade .8s ease .9s forwards;\n  background-image:radial-gradient(circle,rgba(140,138,132,.55) 1.4px,transparent 1.8px);background-size:26px 26px;\n  -webkit-mask-image:radial-gradient(circle at 50% 46%,#000 0,transparent 62%);mask-image:radial-gradient(circle at 50% 46%,#000 0,transparent 62%)}\n.plx-map{--o:.5}\n@keyframes plx-mapin{from{opacity:0;transform:scale(1.15)}to{opacity:.55;transform:none}}\n.plx-map{animation:plx-mapin 1s ease .9s forwards}\n.plx-ripple.c{animation-name:plx-ripple-big;animation-duration:1.4s;animation-delay:1.45s}\n@keyframes plx-ripple-big{0%{opacity:.45;transform:scale(.2)}100%{opacity:0;transform:scale(9)}}\n.plx-ping{opacity:0;animation:plx-fade .01s linear forwards;animation-delay:calc(1.85s + var(--k)*.14s)}\n.plx-pingin{transform-box:fill-box;transform-origin:50% 100%;transform:scale(0);animation:plx-pop .5s cubic-bezier(.2,.9,.3,1.5) forwards,plx-bob 2.2s ease-in-out infinite;animation-delay:calc(1.85s + var(--k)*.14s),calc(2.4s + var(--k)*.3s)}\n@keyframes plx-pop{0%{transform:scale(0) translateY(10px)}100%{transform:scale(1)}}\n@keyframes plx-bob{0%,100%{transform:scale(1) translateY(0)}50%{transform:scale(1) translateY(-4px)}}\n.plx-calm .plx-ping,.plx-calm .plx-ripple.c{display:none}\n.plx-calm .plx-map{animation:plx-fade .5s ease forwards;transform:none}\n@media (prefers-reduced-motion:reduce){.plx .plx-ping{display:none}.plx .plx-map{animation:plx-fade .5s ease forwards;transform:none}}\n";
